internal class SidebarAppearancePreference(private val preferences: SharedPreferences) {
    constructor(context: Context) : this(context.getSharedPreferences("coco-appearance", Context.MODE_PRIVATE))
    fun load(): SidebarAppearanceSettings = SidebarAppearanceCodec.decode(runCatching { preferences.getString(SIDEBAR_APPEARANCE_KEY, null) }.getOrNull())
    /** One owned key in one editor transaction; unrelated preferences survive. */
    fun save(settings: SidebarAppearanceSettings): Boolean {
        val raw = SidebarAppearanceCodec.encode(settings)
        if (raw.toByteArray(Charsets.UTF_8).size > SIDEBAR_APPEARANCE_MAX_BYTES) return false
        preferences.edit().putString(SIDEBAR_APPEARANCE_KEY, raw).apply()
        return true
    }
}

