    val editLabel: String = SavedSidebarStyle.editLabel
    val editColor: Long = SavedSidebarStyle.editColor
    val editSize: Float = SavedSidebarStyle.editSize
    val editIndent: Float = SavedSidebarStyle.editIndent
    val iconsSize: Float = chosen.iconsSize
    val iconsStroke: Float = SavedSidebarStyle.iconsStroke
    val iconsColor: Long = sidebarColorArgb(chosen.iconsColor)
    val iconsColored: Boolean = chosen.iconsColored
    val iconsTiles: Boolean = chosen.iconsTiles
    val iconsTileSize: Float = chosen.iconsTileSize
    val iconsTileRadius: Float = chosen.iconsTileRadius
    val iconsTileOpacity: Float = SavedSidebarStyle.iconsTileOpacity
    val iconsChevrons: Boolean = chosen.iconsChevrons
    val rowsRadius: Float = chosen.rowsRadius
    val rowsFill: Long = sidebarColorArgb(chosen.rowsFill)
    val rowsFillOpacity: Float = chosen.rowsFillOpacity
    val rowsGrouped: Boolean = chosen.rowsGrouped
    val rowsGroupGap: Float = SavedSidebarStyle.rowsGroupGap
    val selectedFill: Long = sidebarColorArgb(chosen.selectedFill)
    val selectedOpacity: Float = chosen.selectedOpacity
    val selectedInk: Long = if (selectedOpacity >= 50f && sidebarLuminance(selectedFill) > 0.4) 0xFF222222L else SavedSidebarStyle.selectedInk
    val selectedMarker: Boolean = SavedSidebarStyle.selectedMarker
    val selectedMarkerColor: Long = SavedSidebarStyle.selectedMarkerColor
    val selectedMarkerWidth: Float = SavedSidebarStyle.selectedMarkerWidth
    val selectedMarkerHeight: Float = SavedSidebarStyle.selectedMarkerHeight
    val selectedBadge: Long = sidebarColorArgb(chosen.selectedBadge)
    val selectedBadgeInk: Long = if (sidebarLuminance(selectedBadge) > 0.4) 0xFF222222L else SavedSidebarStyle.selectedBadgeInk
    val selectedBadgeRadius: Float = SavedSidebarStyle.selectedBadgeRadius
    val selectedBadgeSize: Float = SavedSidebarStyle.selectedBadgeSize
    val quickVisible: Boolean = chosen.quickVisible
    val quickLayout: String = chosen.quickLayout
    val quickHeight: Float = SavedSidebarStyle.quickHeight
    val quickRadius: Float = SavedSidebarStyle.quickRadius
    val quickGap: Float = SavedSidebarStyle.quickGap
    val quickBottom: Float = SavedSidebarStyle.quickBottom
    val quickSize: Float = SavedSidebarStyle.quickSize
    val quickIconSize: Float = SavedSidebarStyle.quickIconSize
    val quickFill: Long = SavedSidebarStyle.quickFill
    val quickInk: Long = SavedSidebarStyle.quickInk
    val quickBorder: Long = SavedSidebarStyle.quickBorder
    val quickBorderWidth: Float = SavedSidebarStyle.quickBorderWidth
    val dividerVisible: Boolean = chosen.dividerVisible
    val dividerColor: Long = SavedSidebarStyle.dividerColor
    val dividerOpacity: Float = SavedSidebarStyle.dividerOpacity
    val dividerThickness: Float = SavedSidebarStyle.dividerThickness
    val dividerInset: Float = SavedSidebarStyle.dividerInset
    val dividerGap: Float = SavedSidebarStyle.dividerGap
    val footerShowLogout: Boolean = chosen.footerShowLogout
    val footerShowVersion: Boolean = chosen.footerShowVersion
    val footerColor: Long = SavedSidebarStyle.footerColor
    val footerFill: Long = SavedSidebarStyle.footerFill
    val footerFillOpacity: Float = SavedSidebarStyle.footerFillOpacity
    val footerRadius: Float = SavedSidebarStyle.footerRadius
    val footerLabel: String = SavedSidebarStyle.footerLabel
    val footerSize: Float = SavedSidebarStyle.footerSize
    val footerVersionSize: Float = SavedSidebarStyle.footerVersionSize
    val footerVersionAlign: String = SavedSidebarStyle.footerVersionAlign
    val footerGap: Float = SavedSidebarStyle.footerGap
    val patternKind: String = chosen.patternKind
    val patternColor: Long = sidebarColorArgb(chosen.patternColor)
    val patternOpacity: Float = chosen.patternOpacity
    val patternSize: Float = chosen.patternSize
    val patternSpacing: Float = chosen.patternSpacing
    val patternStroke: Float = SavedSidebarStyle.patternStroke
    val patternRotation: Float = SavedSidebarStyle.patternRotation
    val behaviorDuration: Float = chosen.behaviorDuration
    val behaviorSwipeOpen: Boolean = chosen.behaviorSwipeOpen
    val behaviorSwipeClose: Boolean = chosen.behaviorSwipeClose
    val behaviorHaptic: String = SavedSidebarStyle.behaviorHaptic
    val behaviorScrim: Float = chosen.behaviorScrim
    val behaviorBlur: Float = SavedSidebarStyle.behaviorBlur
    val behaviorChatBackground: Long = SavedSidebarStyle.behaviorChatBackground
    val items: List<SavedSidebarStyle.Item> = Collections.unmodifiableList(chosen.itemOrder.mapIndexed { index, id ->
        val item = SavedSidebarStyle.items.first { it.id == id }
        item.copy(color = chosen.itemColors[id]?.let(::sidebarColorArgb) ?: item.color,
            visible = id !in chosen.hiddenItems, order = index + 1)
    })
    fun metrics(screenWidth: Float): SavedSidebarStyle.Metrics {
        val viewport = screenWidth.takeIf { it.isFinite() && it > 0f } ?: 1f
        val panel = viewport * geometryWidth / 100f
        val inset = minOf(geometryInset, maxOf(6f, (panel - 120f) / 2f))
        val content = maxOf(64f, panel - 2f * inset)
        val padding = minOf(profilePadding, content / 10f)
        val layout = if (content < 112f) "center" else profileLayout
        val avatar = if (layout == "center") minOf(avatarSize, content - 2f * padding)
            else minOf(avatarSize, maxOf(26f, content - 2f * padding - (if (profileShowClose) 44f else 0f) - 2f * profileGap - 60f))
        val rowPadding = minOf(geometryRowPaddingX, content / 6f)
        val rowContent = content - 2f * rowPadding
        return SavedSidebarStyle.Metrics(panel, inset, content, layout, padding, avatar, rowPadding, rowContent,
            minOf(iconsTileSize, maxOf(0f, (rowContent - iconsSize) / 2f)),
            minOf(geometryIconGap, content / 8f), minOf(editIndent, content / 5f),
            quickLayout == "row" && content >= 136f + quickGap)
    }

}

internal val SidebarAppearanceSettings.resolved: ResolvedSidebarStyle get() = ResolvedSidebarStyle(this)
internal fun SidebarAppearanceSettings.resolved(): ResolvedSidebarStyle = resolved
internal fun resolveSidebarAppearance(settings: SidebarAppearanceSettings): ResolvedSidebarStyle = settings.resolved
